type Item = { name: string; count: number };
type Result = { ok: true; value: string } | { ok: false; error: string };

function summarize(items: Item[]): string {
  if (items.length === 0) return "No items";
  return items.map(item => `${item.name}: ${item.count}`).join("\n");
}

export function parseAndSummarize(input: string): Result {
  let raw: unknown;
  try {
    raw = JSON.parse(input);
  } catch {
    return { ok: false, error: "Invalid JSON" };
  }
  if (!Array.isArray(raw)) return { ok: false, error: "Expected items" };
  // The caller's notification service rejects batches larger than 100.
  if (raw.length > 100) return { ok: false, error: "Too many items" };
  const items: Item[] = [];
  for (const candidate of raw) {
    if (candidate === null || typeof candidate !== "object" ||
        typeof candidate.name !== "string" ||
        !Number.isSafeInteger(candidate.count) || candidate.count < 0) {
      return { ok: false, error: "Invalid item" };
    }
    items.push({ name: candidate.name, count: candidate.count });
  }
  return { ok: true, value: summarize(items) };
}

